//! Quantities. Each is its own type, hand-written rather than generated by a
//! macro, so each derives only what it means: a position is ordered, a length
//! is not hashed, none has a `Default` it did not ask for, and none converts
//! from a bare integer.
//!
//! The integer leaves through one named seam, `get()`, and enters through
//! named constructors that say where it came from. Stored types are as narrow
//! as their range (`u32` for a line length); `cargo xtask budgets` counts the
//! seams so a new one is a reviewed change.

use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};

/// An absolute position in the input stream, in bytes from its start.
#[derive(
    Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, FromBytes, IntoBytes, Immutable, KnownLayout,
)]
#[repr(transparent)]
pub struct BytePos(pub(crate) u64);

impl BytePos {
    /// The start of the stream.
    pub const ZERO: Self = Self(0);

    /// The position `by` bytes further on. Saturates at the end of the range,
    /// and says so in its name: a stream of 2^64 bytes is refused, not wrapped.
    #[must_use]
    pub const fn saturating_advance(self, by: ReadLen) -> Self {
        // `usize` is at most 64 bits on every target this builds for, so the
        // widening is exact; the one `as` here is counted by `xtask budgets`.
        Self(self.0.saturating_add(by.0 as u64))
    }

    /// The raw position, for interop. The only way out.
    #[must_use]
    pub const fn get(self) -> u64 {
        self.0
    }
}

/// The length of one read: how many bytes a host handed over at once.
///
/// Distinct from [`ByteLen`] because the two have different ranges -- a read
/// may be larger than any line we keep -- and a type that silently narrowed
/// one into the other would truncate without saying so.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
#[repr(transparent)]
pub struct ReadLen(pub(crate) usize);

impl ReadLen {
    /// The single place a slice length becomes a read length.
    #[must_use]
    pub const fn of(bytes: &[u8]) -> Self {
        Self(bytes.len())
    }

    /// One byte.
    pub const ONE: Self = Self(1);
}

/// The length of a line, in bytes, newline excluded. Stored as `u32`: a line
/// longer than 4 GiB is refused and counted ([`crate::Pushed::Refused`]), never
/// wrapped.
#[derive(
    Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, FromBytes, IntoBytes, Immutable, KnownLayout,
)]
#[repr(transparent)]
pub struct ByteLen(pub(crate) u32);

impl ByteLen {
    /// An empty line.
    pub const ZERO: Self = Self(0);

    /// One byte longer, or `None` at the top of the range.
    #[must_use]
    pub const fn checked_grow(self) -> Option<Self> {
        match self.0.checked_add(1) {
            Some(n) => Some(Self(n)),
            None => None,
        }
    }

    /// The raw length, for interop. The only way out.
    #[must_use]
    pub const fn get(self) -> u32 {
        self.0
    }
}

/// How many words a line holds. Saturates, and says so in its name.
#[derive(
    Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, FromBytes, IntoBytes, Immutable, KnownLayout,
)]
#[repr(transparent)]
pub struct WordCount(pub(crate) u32);

impl WordCount {
    /// No words.
    pub const ZERO: Self = Self(0);

    /// One more word, saturating at the top of the range.
    #[must_use]
    pub const fn saturating_incr(self) -> Self {
        Self(self.0.saturating_add(1))
    }

    /// The raw count, for interop. The only way out.
    #[must_use]
    pub const fn get(self) -> u32 {
        self.0
    }
}

/// A point in time, in milliseconds on the host's monotonic clock.
///
/// The core never reads a clock (pillar 2): the host reads one and hands the
/// time in as [`crate::Event::Tick`]. Only the host creates these.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
#[repr(transparent)]
pub struct Millis(pub(crate) u64);

impl Millis {
    /// The start of the host's clock.
    pub const ZERO: Self = Self(0);

    /// The host's clock reading, in milliseconds. The entry seam.
    #[must_use]
    pub const fn from_host(ms: u64) -> Self {
        Self(ms)
    }

    /// How long ago `earlier` was. A clock that stepped backwards reads as
    /// no time at all rather than as a huge interval.
    #[must_use]
    pub const fn since(self, earlier: Self) -> Elapsed {
        Elapsed(self.0.saturating_sub(earlier.0))
    }
}

/// An interval. There is no public constructor from an integer except the
/// named threshold below: an `Elapsed` you hold came from [`Millis::since`] or
/// is a deliberate configuration value, never a stray number.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
#[repr(transparent)]
pub struct Elapsed(pub(crate) u64);

impl Elapsed {
    /// A configured threshold, in milliseconds. The entry seam for settings.
    #[must_use]
    pub const fn threshold_ms(ms: u64) -> Self {
        Self(ms)
    }
}

/// How many times something happened. For counters the host reads: refusals,
/// drops. Saturates, and says so in its name.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
#[repr(transparent)]
pub struct Tally(pub(crate) u64);

impl Tally {
    /// Nothing yet.
    pub const ZERO: Self = Self(0);

    /// One more, saturating at the top of the range.
    #[must_use]
    pub const fn saturating_incr(self) -> Self {
        Self(self.0.saturating_add(1))
    }

    /// Both tallies together, saturating at the top of the range.
    #[must_use]
    pub const fn saturating_add(self, other: Self) -> Self {
        Self(self.0.saturating_add(other.0))
    }

    /// The raw count, for interop. The only way out.
    #[must_use]
    pub const fn get(self) -> u64 {
        self.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_clock_that_steps_back_reads_as_no_time() {
        assert_eq!(Millis(5).since(Millis(9)), Elapsed(0));
        assert_eq!(Millis(9).since(Millis(5)), Elapsed(4));
    }

    #[test]
    fn a_line_length_refuses_rather_than_wraps() {
        assert_eq!(ByteLen(u32::MAX).checked_grow(), None);
        assert_eq!(ByteLen(7).checked_grow(), Some(ByteLen(8)));
    }

    #[test]
    fn tallies_add_and_saturate() {
        assert_eq!(Tally(2).saturating_add(Tally(3)).get(), 5);
        assert_eq!(Tally(u64::MAX).saturating_add(Tally(1)).get(), u64::MAX);
    }

    #[test]
    fn counts_and_positions_saturate_by_name() {
        assert_eq!(WordCount(u32::MAX).saturating_incr(), WordCount(u32::MAX));
        assert_eq!(
            BytePos(u64::MAX).saturating_advance(ReadLen(3)),
            BytePos(u64::MAX)
        );
        assert_eq!(BytePos(2).saturating_advance(ReadLen::ONE).get(), 3);
    }
}
